/**
 * MJPEG relay for serve-sim's own viewer (the default page).
 *
 * serve-sim streams the Simulator as full-resolution JPEGs (an iPhone 17 Pro
 * frame is 1206x2622, about 230 KB) and re-sends the same picture several
 * times a second even when nothing moves. Measured on a GitHub macOS runner on
 * 2026-11-01: 12-16 frames/s of ~231 KB, i.e. 22-30 Mbit/s through the tunnel,
 * idle or not. On a home connection that queues up: what you see lags behind
 * what you tap, and when one frame takes more than 2 s to arrive serve-sim's
 * viewer dims the phone with its "Connecting..." overlay until the next one
 * lands (the black flicker).
 *
 * The gate serves browser requests for `<helper>/stream.mjpeg` from here instead
 * of piping serve-sim's bytes through. One upstream connection per stream path,
 * shared by every viewer, and:
 *   - identical frames are dropped (serve-sim's idle re-sends);
 *   - at most `fps` frames per second, but the last frame of a burst always goes
 *     out (the screen never stops on a stale picture);
 *   - frames are scaled so the longest side is at most `maxDimension` and
 *     re-encoded at `quality` (FFmpeg, from ffmpeg-static, which the runner
 *     already installs for the WebRTC peer); without FFmpeg, frames pass through;
 *   - each viewer gets the newest frame its connection can take: while its
 *     socket is still flushing, newer frames replace older ones instead of
 *     queueing behind them, so a slow link drops frames instead of lagging;
 *   - the newest frame is repeated once a second while idle, so serve-sim's
 *     viewer (which dims after 2 s without a frame) never mistakes a still
 *     screen for a dead stream.
 */
const http = require('node:http');
const { spawn } = require('node:child_process');
const { createJpegSplitter } = require('./peer/mjpeg.cjs');
const { videoConfigFromEnv } = require('./runtime.cjs');

const BOUNDARY = 'frame';
const KEEPALIVE_MS = 1000;
const CLOSE_GRACE_MS = 3000;
/** A viewer whose socket still holds more than this is "busy": newer frames replace the waiting one. */
const CLIENT_BUSY_BYTES = 64 * 1024;
/** Frames waiting inside FFmpeg before newer ones replace the next input (FFmpeg's pipe input lags ~2 frames). */
const TRANSCODER_MAX_IN_FLIGHT = 4;

/** Relay settings from the runner environment (the workflow passes --max-dimension/--fps/--quality). */
function relayConfigFromEnv(env = process.env) {
  const v = videoConfigFromEnv(env);
  return { enabled: v.relay, maxDimension: v.maxDimension, fps: v.fps, quality: v.quality };
}

/** JPEG quality 0.05..1 -> FFmpeg's mjpeg -q:v (2 best .. 31 worst). 0.6 -> 10. */
function qscaleFor(quality) {
  return Math.max(2, Math.min(31, Math.round(2 + (1 - quality) * 20)));
}

/** FFmpeg scale filter: longest side at most maxDimension, never upscaled, even sizes. */
function scaleFilter(maxDimension) {
  const d = Math.round(maxDimension);
  return `scale='if(gte(iw,ih),min(${d},trunc(iw/2)*2),-2)':'if(gte(iw,ih),-2,min(${d},trunc(ih/2)*2))':flags=area`;
}

function buildTranscoderArgs({ maxDimension, quality }) {
  const vf = maxDimension > 0 ? ['-vf', scaleFilter(maxDimension)] : [];
  return [
    '-hide_banner', '-loglevel', 'error', '-nostdin',
    '-threads', '1',
    '-probesize', '32', '-analyzeduration', '0', '-fflags', 'nobuffer', '-flags', 'low_delay',
    '-f', 'image2pipe', '-c:v', 'mjpeg', '-i', 'pipe:0',
    ...vf,
    '-threads', '1', '-fps_mode', 'passthrough',
    '-c:v', 'mjpeg', '-pix_fmt', 'yuvj420p', '-q:v', String(qscaleFor(quality)),
    '-f', 'image2pipe', 'pipe:1',
  ];
}

/** True for serve-sim's MJPEG stream path (`/stream.mjpeg`, `/helper/<udid>/stream.mjpeg`). */
function isMjpegStreamPath(pathname) {
  return /(^|\/)stream\.mjpeg$/.test(pathname);
}

function sameFrame(a, b) {
  return Boolean(a && b && a.length === b.length && a.equals(b));
}

function partFor(jpeg) {
  const head = Buffer.from(`--${BOUNDARY}\r\nContent-Type: image/jpeg\r\nContent-Length: ${jpeg.length}\r\n\r\n`);
  return Buffer.concat([head, jpeg, Buffer.from('\r\n')]);
}

/**
 * Scales/re-encodes JPEGs with one long-lived FFmpeg. FFmpeg's piped JPEG input
 * only releases a frame once ~2 more have arrived, so when the input goes quiet
 * the last real frame is pushed out with two throw-away copies; outputs are
 * matched to inputs in order and the copies are dropped.
 */
class Transcoder {
  constructor({ ffmpegPath, maxDimension, quality, fps, onFrame, onFail, log }) {
    this.ffmpegPath = ffmpegPath;
    this.args = buildTranscoderArgs({ maxDimension, quality });
    this.onFrame = onFrame;
    this.onFail = onFail;
    this.log = log;
    this.minGapMs = 1000 / fps;
    this.inputGapMs = 0;
    this.lastWriteAt = 0;
    this.fifo = [];
    this.next = null;
    this.last = null;
    this.flushTimer = null;
    this.proc = null;
    this.failed = false;
    this.framesIn = 0;
    this.framesOut = 0;
  }

  start() {
    try {
      this.proc = spawn(this.ffmpegPath, this.args, { stdio: ['pipe', 'pipe', 'pipe'] });
    } catch (err) {
      this._fail(err.message);
      return;
    }
    const proc = this.proc;
    const splitter = createJpegSplitter((jpeg) => {
      const kind = this.fifo.shift();
      if (kind === 'real') {
        this.framesOut++;
        this.onFrame(Buffer.from(jpeg));
      }
      if (this.next && this.fifo.length < TRANSCODER_MAX_IN_FLIGHT) {
        const n = this.next;
        this.next = null;
        this._write(n);
      }
    });
    proc.stdout.on('data', (chunk) => splitter.push(chunk));
    proc.stderr.on('data', (d) => {
      const msg = d.toString().trim();
      if (msg) this.log(`[relay ffmpeg] ${msg.split('\n').pop()}`);
    });
    proc.stdin.on('error', () => {});
    proc.on('error', (err) => this._fail(err.message));
    proc.on('close', (code) => {
      if (this.proc === proc && !this.stopped) this._fail(`FFmpeg exited with code ${code}`);
    });
  }

  push(jpeg) {
    if (this.failed || !this.proc) return false;
    if (this.fifo.length >= TRANSCODER_MAX_IN_FLIGHT) {
      this.next = jpeg; // newest wins while FFmpeg catches up
      return true;
    }
    this._write(jpeg);
    return true;
  }

  /** Twice the usual gap between frames (at least 1.5 fps-slots): a steady stream is never padded. */
  _flushDelay() {
    const gap = this.inputGapMs || this.minGapMs;
    return Math.min(300, Math.max(40, Math.round(Math.max(2 * gap, 1.5 * this.minGapMs))));
  }

  _write(jpeg) {
    const now = Date.now();
    if (this.lastWriteAt) {
      const gap = Math.min(1000, now - this.lastWriteAt);
      this.inputGapMs = this.inputGapMs ? this.inputGapMs * 0.8 + gap * 0.2 : gap;
    }
    this.lastWriteAt = now;
    this.last = jpeg;
    this.framesIn++;
    this.fifo.push('real');
    this._send(jpeg);
    if (this.flushTimer) clearTimeout(this.flushTimer);
    this.flushTimer = setTimeout(() => {
      this.flushTimer = null;
      if (this.last !== jpeg || this.failed) return;
      this.fifo.push('flush', 'flush');
      this._send(jpeg);
      this._send(jpeg);
    }, this._flushDelay());
  }

  _send(buf) {
    try { this.proc.stdin.write(buf); } catch {}
  }

  _fail(reason) {
    if (this.failed) return;
    this.failed = true;
    this.stop();
    this.onFail(reason);
  }

  stop() {
    this.stopped = true;
    if (this.flushTimer) clearTimeout(this.flushTimer);
    this.flushTimer = null;
    if (this.proc) {
      try { this.proc.stdin.end(); } catch {}
      try { this.proc.kill('SIGKILL'); } catch {}
    }
    this.proc = null;
  }
}

/** One serve-sim stream path, shared by every viewer of it. */
class RelaySource {
  constructor(relay, key, upstreamPath) {
    this.relay = relay;
    this.key = key;
    this.upstreamPath = upstreamPath;
    this.clients = new Set();
    this.waiting = new Set();
    this.req = null;
    this.lastSource = null;
    this.lastOut = null;
    this.lastAcceptedAt = 0;
    this.lastBroadcastAt = 0;
    this.pendingSource = null;
    this.paceTimer = null;
    this.keepaliveTimer = null;
    this.closeTimer = null;
    this.transcoder = null;
    this.retryTimer = null;
    this.closed = false;
    this.stats = { sourceFrames: 0, duplicates: 0, accepted: 0, sent: 0, bytesSent: 0, skippedForSlowViewer: 0 };
  }

  get config() { return this.relay.config; }

  addClient(req, res) {
    if (this.closeTimer) { clearTimeout(this.closeTimer); this.closeTimer = null; }
    const client = { res, pending: null };
    if (res.socket) {
      res.socket.setNoDelay(true);
      res.socket.setKeepAlive(true, 10000);
    }
    const drop = () => this.removeClient(client);
    res.on('close', drop);
    res.on('error', drop);
    res.on('drain', () => {
      if (client.pending) {
        const p = client.pending;
        client.pending = null;
        this._deliver(client, p);
      }
    });
    if (this.started) {
      this._admit(client);
    } else {
      this.waiting.add(client);
      this._start();
    }
  }

  _admit(client) {
    const { res } = client;
    if (res.destroyed || res.writableEnded) return;
    res.writeHead(200, {
      'Content-Type': `multipart/x-mixed-replace; boundary=${BOUNDARY}`,
      'Cache-Control': 'no-cache, no-store, no-transform',
      Pragma: 'no-cache',
      'X-Accel-Buffering': 'no',
      Connection: 'keep-alive',
      'Access-Control-Allow-Origin': '*',
    });
    if (typeof res.flushHeaders === 'function') res.flushHeaders();
    this.clients.add(client);
    if (this.lastOut) this._deliver(client, this.lastOut);
  }

  removeClient(client) {
    this.clients.delete(client);
    this.waiting.delete(client);
    if (this.clients.size === 0 && this.waiting.size === 0 && !this.closeTimer) {
      // A reload reconnects within a second; keep FFmpeg and the upstream warm.
      this.closeTimer = setTimeout(() => this.close(), CLOSE_GRACE_MS);
    }
  }

  _start() {
    if (!this.keepaliveTimer) {
      this.keepaliveTimer = setInterval(() => this._keepalive(), KEEPALIVE_MS / 2);
    }
    this._connect();
  }

  /** (Re)connect to serve-sim. Admitted viewers stay connected (and fed by the keepalive) meanwhile. */
  _connect() {
    if (this.req || this.closed) return;
    const { host, port } = this.relay;
    const retry = (ms) => {
      this.req = null;
      if (this.closed) return;
      if (this.clients.size === 0 && this.waiting.size === 0) { this.close(); return; }
      if (!this.retryTimer) this.retryTimer = setTimeout(() => { this.retryTimer = null; this._connect(); }, ms);
    };
    const failWaiting = (status, contentType, body) => {
      for (const c of this.waiting) {
        try {
          if (!c.res.headersSent) c.res.writeHead(status, { 'Content-Type': contentType });
          c.res.end(body);
        } catch {}
      }
      this.waiting.clear();
    };
    const req = http.get({ host, port, path: this.upstreamPath, headers: { 'Accept-Encoding': 'identity' } }, (up) => {
      if (up.statusCode !== 200) {
        const chunks = [];
        up.on('data', (c) => chunks.push(c));
        up.on('end', () => {
          // Before the first frame, pass serve-sim's answer on (e.g. 404 for an unknown device).
          if (!this.started) failWaiting(up.statusCode || 502, up.headers['content-type'] || 'text/plain', Buffer.concat(chunks));
          retry(1000);
        });
        return;
      }
      this.started = true;
      if (up.socket) up.socket.setNoDelay(true);
      this._ensureTranscoder();
      for (const c of this.waiting) this._admit(c);
      this.waiting.clear();
      const splitter = createJpegSplitter((jpeg) => this._onSourceFrame(jpeg));
      up.on('data', (chunk) => splitter.push(chunk));
      up.on('end', () => retry(300));
      up.on('error', () => retry(300));
    });
    req.on('error', (err) => {
      if (!this.started) failWaiting(502, 'text/plain', `Upstream error: ${err.message}`);
      retry(1000);
    });
    this.req = req;
  }

  _ensureTranscoder() {
    if (this.transcoder || this.relay.passthrough) return;
    const { maxDimension, quality, fps } = this.config;
    const ffmpegPath = this.relay.ffmpegPath;
    if (!ffmpegPath) return;
    this.transcoder = new Transcoder({
      ffmpegPath, maxDimension, quality, fps,
      log: this.relay.log,
      onFrame: (jpeg) => this._broadcast(jpeg),
      onFail: (reason) => {
        this.relay.log(`[relay] FFmpeg unavailable (${reason}); sending serve-sim's frames unscaled`);
        this.relay.passthrough = true;
        this.transcoder = null;
        if (this.lastSource) this._broadcast(this.lastSource);
      },
    });
    this.transcoder.start();
  }

  _onSourceFrame(jpeg) {
    this.stats.sourceFrames++;
    if (sameFrame(jpeg, this.lastSource)) {
      this.stats.duplicates++;
      return;
    }
    this.lastSource = Buffer.from(jpeg);
    this.pendingSource = this.lastSource;
    const interval = 1000 / this.config.fps;
    const wait = this.lastAcceptedAt + interval - Date.now();
    if (wait <= 0) {
      this._accept();
    } else if (!this.paceTimer) {
      // Too soon: hold the newest frame and send it at the next slot.
      this.paceTimer = setTimeout(() => { this.paceTimer = null; this._accept(); }, Math.ceil(wait));
    }
  }

  _accept() {
    const jpeg = this.pendingSource;
    if (!jpeg) return;
    this.pendingSource = null;
    this.lastAcceptedAt = Date.now();
    this.stats.accepted++;
    if (this.transcoder && this.transcoder.push(jpeg)) return;
    this._broadcast(jpeg);
  }

  _broadcast(jpeg) {
    this.lastOut = jpeg;
    this.lastBroadcastAt = Date.now();
    for (const client of this.clients) this._deliver(client, jpeg);
  }

  _deliver(client, jpeg) {
    const { res } = client;
    if (res.destroyed || res.writableEnded) return;
    const queued = res.writableLength + (res.socket ? res.socket.writableLength : 0);
    if (res.writableNeedDrain || queued > CLIENT_BUSY_BYTES) {
      if (client.pending) this.stats.skippedForSlowViewer++;
      client.pending = jpeg; // newest frame waits; older ones are dropped, never queued
      return;
    }
    const part = partFor(jpeg);
    this.stats.sent++;
    this.stats.bytesSent += part.length;
    res.write(part);
  }

  _keepalive() {
    if (!this.lastOut || this.clients.size === 0) return;
    if (Date.now() - this.lastBroadcastAt >= KEEPALIVE_MS) this._broadcast(this.lastOut);
  }

  close() {
    if (this.closed) return;
    this.closed = true;
    this.relay.sources.delete(this.key);
    for (const t of [this.paceTimer, this.closeTimer, this.retryTimer]) if (t) clearTimeout(t);
    if (this.keepaliveTimer) clearInterval(this.keepaliveTimer);
    if (this.transcoder) this.transcoder.stop();
    this.transcoder = null;
    if (this.req) { try { this.req.destroy(); } catch {} }
    this.req = null;
    for (const c of [...this.clients, ...this.waiting]) { try { c.res.end(); } catch {} }
    this.clients.clear();
    this.waiting.clear();
  }
}

class MjpegRelay {
  constructor({ host = '127.0.0.1', port, config = relayConfigFromEnv(), ffmpegPath, log = console.log } = {}) {
    this.host = host;
    this.port = port;
    this.config = config;
    this.log = log;
    this.sources = new Map();
    this.ffmpegPath = ffmpegPath === undefined ? findFfmpeg() : ffmpegPath;
    const needsTranscode = config.maxDimension > 0 || config.quality < 1;
    this.passthrough = !this.ffmpegPath || !needsTranscode;
  }

  describe() {
    const c = this.config;
    const scale = this.passthrough ? 'unscaled' : `longest side <= ${c.maxDimension || 'native'} px, quality ${c.quality}`;
    return `MJPEG relay: <= ${c.fps} fps, ${scale}, duplicates dropped, newest frame wins on slow links`;
  }

  /** Serve one viewer of `pathname` (a serve-sim stream.mjpeg path). */
  handle(req, res, pathname, search = '') {
    const params = new URLSearchParams(search);
    params.set('raw', '1');
    const upstreamPath = `${pathname}?${params.toString()}`;
    const key = upstreamPath;
    let source = this.sources.get(key);
    if (!source || source.closed) {
      source = new RelaySource(this, key, upstreamPath);
      this.sources.set(key, source);
    }
    source.addClient(req, res);
  }

  stats() {
    const out = {};
    for (const [key, s] of this.sources) {
      out[key] = { ...s.stats, viewers: s.clients.size, transcoding: Boolean(s.transcoder) };
    }
    return { config: this.config, passthrough: this.passthrough, sources: out };
  }

  close() {
    for (const s of [...this.sources.values()]) s.close();
  }
}

function findFfmpeg() {
  if (process.env.FLUTTER_REMOTE_FFMPEG) return process.env.FLUTTER_REMOTE_FFMPEG;
  try {
    // eslint-disable-next-line global-require
    const p = require('ffmpeg-static');
    if (p && require('node:fs').existsSync(p)) return p;
  } catch {}
  return null;
}

module.exports = {
  MjpegRelay,
  relayConfigFromEnv,
  qscaleFor,
  scaleFilter,
  buildTranscoderArgs,
  isMjpegStreamPath,
};
